import java.net.URLDecoder
import java.nio.charset.StandardCharsets
import java.text.Normalizer
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.security.SecureRandom

object AuthConfig {
  private val secretBytes: Array[Byte] = {
    val sr = new SecureRandom()
    val key = new Array[Byte](32)
    sr.nextBytes(key)
    key
  }
  def getSecret: Array[Byte] = secretBytes.clone()
}

case class Session(userId: String, roles: Set[String], expiry: Long)

class SessionManager {
  private val sessions = new java.util.concurrent.ConcurrentHashMap[String, Session]()

  def createSession(userId: String, roles: Set[String]): String = {
    val token = generateToken()
    val expiry = System.currentTimeMillis() + 3600000L
    sessions.put(token, Session(userId, roles, expiry))
    token
  }

  def getSession(token: String): Option[Session] = {
    Option(sessions.get(token)).filter(_.expiry > System.currentTimeMillis())
  }

  private def generateToken(): String = {
    val bytes = new Array[Byte](32)
    new SecureRandom().nextBytes(bytes)
    Base64.getUrlEncoder.withoutPadding().encodeToString(bytes)
  }
}

class PathNormalizer {
  /**
   * Normalizes a URL path for consistent routing and authorization.
   * Steps:
   * 1. Resolve relative path segments (. and ..) on raw path
   * 2. Reject any path containing encoded separators (%2F, %5C)
   * 3. URL-decode the path (only after structural validation)
   * 4. Apply Unicode NFC normalization for consistent comparison
   * 5. Collapse multiple slashes
   * 6. Remove trailing slash
   * 7. Final validation: reject if decoded path differs structurally
   */
  def normalize(rawPath: String): Either[String, String] = {
    // Step 0: Reject encoded path separators BEFORE decoding
    if (containsEncodedSeparators(rawPath)) {
      return Left("400 Bad Request: encoded path separators not allowed")
    }
    // Step 1: Resolve relative segments on the raw (still-encoded) path
    val resolved = resolveRelative(rawPath)
    // Step 2: Reject path traversal attempts
    if (resolved.contains("..") || resolved.contains("./")) {
      return Left("400 Bad Request: path traversal detected")
    }
    // Step 3: URL decode (safe now - no encoded separators)
    val decoded = URLDecoder.decode(resolved, StandardCharsets.UTF_8.name())
    // Step 4: Unicode NFC normalization
    val nfcNormalized = Normalizer.normalize(decoded, Normalizer.Form.NFC)
    // Step 5: Reject if normalization introduced path separators
    if (nfcNormalized.split("/").length != resolved.split("/").length) {
      return Left("400 Bad Request: normalization changed path structure")
    }
    // Step 6: Collapse multiple slashes
    val collapsed = nfcNormalized.replaceAll("/+", "/")
    // Step 7: Remove trailing slash (but keep root)
    val result = if (collapsed.length > 1 && collapsed.endsWith("/")) collapsed.dropRight(1)
                 else collapsed
    // Step 8: Final structural validation
    if (result.contains("..")) Left("400 Bad Request: path traversal in normalized path")
    else Right(result)
  }

  private def containsEncodedSeparators(path: String): Boolean = {
    val upper = path.toUpperCase
    upper.contains("%2F") || upper.contains("%5C") ||
    upper.contains("%2E%2E") || upper.contains("%252F")
  }

  private def resolveRelative(path: String): String = {
    val segments = path.split("/").toList
    val resolved = segments.foldLeft(List.empty[String]) { (acc, seg) =>
      seg match {
        case "." => acc
        case ".." => if (acc.nonEmpty) acc.init else acc
        case other => acc :+ other
      }
    }
    resolved.mkString("/")
  }
}

class AuthorizationEngine {
  // Access control rules: path prefix -> required roles
  private val rules: List[(String, Set[String])] = List(
    ("/admin", Set("admin")),
    ("/api/users", Set("admin", "user-manager")),
    ("/api/billing", Set("admin", "billing")),
    ("/api/reports", Set("admin", "analyst")),
    ("/internal", Set("admin", "service-account")),
    ("/public", Set.empty)  // accessible to all authenticated users
  )

  /**
   * Returns true only when the path exactly equals the prefix or is a
   * proper sub-path (prefix followed by a path separator). This prevents
   * unrelated paths such as "/publicadmin" from incorrectly matching
   * the "/public" rule.
   */
  private def isPrefixMatch(path: String, prefix: String): Boolean = {
    path == prefix || path.startsWith(prefix + "/")
  }

  /**
   * Check if the given roles are authorized to access the path.
   * Returns true if access is permitted.
   */
  def isAuthorized(normalizedPath: String, userRoles: Set[String]): Boolean = {
    // Find the most specific matching rule using segment-boundary-aware matching
    val matchingRules = rules.filter { case (prefix, _) =>
      isPrefixMatch(normalizedPath, prefix)
    }.sortBy { case (prefix, _) => -prefix.length }  // most specific first

    matchingRules.headOption match {
      case Some((_, requiredRoles)) =>
        if (requiredRoles.isEmpty) true  // public endpoint
        else userRoles.intersect(requiredRoles).nonEmpty
      case None =>
        // No matching rule - deny by default
        false
    }
  }
}

class RequestRouter {
  private val normalizer = new PathNormalizer()
  private val authEngine = new AuthorizationEngine()

  /**
   * Routes a request after performing path normalization and authorization.
   * The path is normalized ONCE and used for both authorization and routing.
   */
  def handleRequest(rawPath: String, session: Session): Either[String, String] = {
    normalizer.normalize(rawPath) match {
      case Left(error) => Left(error)
      case Right(normalizedPath) =>
        if (!authEngine.isAuthorized(normalizedPath, session.roles)) {
          Left(s"403 Forbidden: insufficient permissions for $normalizedPath")
        } else {
          Right(dispatch(normalizedPath, session))
        }
    }
  }

  private def dispatch(path: String, session: Session): String = {
    path match {
      case p if p.startsWith("/admin") => s"Admin panel for ${session.userId}"
      case p if p.startsWith("/api/") => s"API response for ${session.userId}"
      case p if p.startsWith("/internal") => s"Internal service response"
      case p if p.startsWith("/public") => s"Public content"
      case _ => "404 Not Found"
    }
  }
}

/**
 * Middleware that handles the full request lifecycle.
 * Uses a two-phase approach:
 *   Phase 1: Authenticate (validate session token)
 *   Phase 2: Authorize and route (normalize path, check permissions, dispatch)
 */
class RequestMiddleware {
  private val sessionManager = new SessionManager()
  private val router = new RequestRouter()

  def processRequest(rawPath: String, authToken: Option[String]): String = {
    // Phase 1: Authentication
    val session = authToken.flatMap(sessionManager.getSession)
    session match {
      case None => "401 Unauthorized: invalid or expired session"
      case Some(s) =>
        // Phase 2: Authorization and routing
        router.handleRequest(rawPath, s) match {
          case Left(error) => error
          case Right(response) => response
        }
    }
  }

  def login(userId: String, roles: Set[String]): String = {
    sessionManager.createSession(userId, roles)
  }
}

/**
 * Backend service that processes requests from the middleware.
 */
class BackendService {
  private val middleware = new RequestMiddleware()

  /**
   * Entry point from the HTTP layer.
   * The raw path comes directly from the HTTP request line.
   */
  def serve(rawPath: String, authHeader: Option[String]): String = {
    middleware.processRequest(rawPath, authHeader)
  }

  /**
   * Creates test sessions for demonstration.
   */
  def createTestUser(userId: String, roles: Set[String]): String = {
    middleware.login(userId, roles)
  }
}

// Application entry point
object Application {
  def main(args: Array[String]): Unit = {
    val service = new BackendService()

    // Create a regular user with limited permissions
    val userToken = service.createTestUser("alice", Set("user"))

    // Normal access to public endpoint - should succeed
    println(service.serve("/public/docs", Some(userToken)))

    // Direct access to admin - should be denied
    println(service.serve("/admin/dashboard", Some(userToken)))

    // Attempted bypass with encoded separators - should be rejected
    println(service.serve("/public/..%2Fadmin/dashboard", Some(userToken)))

    // Attempted bypass with double encoding - should be rejected
    println(service.serve("/public/%252F../admin", Some(userToken)))

    // Attempted bypass with dot-dot - should be resolved safely
    println(service.serve("/public/../admin/dashboard", Some(userToken)))
  }
}
